import{_ as r,a0 as l,w as p,s as d,ao as a,I as t,a1 as n,A as o,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中創建一個共享目錄 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中創建一個共享目錄 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中創建一個共享目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中創建一個共享目錄 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170201 How to Create a Shared Directory for All Users in Linux","title":"如何在 Linux 中創建一個共享目錄","tag":"201702","desc":""},"relativePath":"201702/20170201 How to Create a Shared Directory for All Users in Linux.md","filePath":"[post].md"}'),u={name:"201702/20170201 How to Create a Shared Directory for All Users in Linux.md"};function g(h,s,m,k,c,w){const e=l("Link");return p(),d("div",null,[s[17]||(s[17]=a(`<h1 id="如何在-linux-中創建一個共享目錄" tabindex="-1">如何在 Linux 中創建一個共享目錄 <a class="header-anchor" href="#如何在-linux-中創建一個共享目錄" aria-label="Permalink to “如何在 Linux 中創建一個共享目錄”">​</a></h1><p>作為系統管理員，你可能有一個特定目錄，你希望為 Linux 服務器上的每個用户授予讀/寫訪問權限。在本指南中，我們將回顧如何在 Linux 中對特定目錄（共享目錄）上的所有用户啓用寫訪問。</p><p>這要求設置適當的訪問權限，而最有效、可靠的方法是為所有要共享或對特定目錄的寫訪問權的用户分配一個公共組。</p><p>如果你係統中還沒有存在這個目錄和公眾組，用下面的命令創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /var/www/reports/</span></span>
<span class="line"><span>$ sudo groupadd project</span></span></code></pre></div><p>接着將對目錄 <code>/var/www/reports/</code> 有寫權限的用户添加到 <code>project</code> 組中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G project tecmint</span></span></code></pre></div>`,7)),t("p",null,[n(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/01/Create-Common-Directory-Group.png"},{default:o(()=>[...s[0]||(s[0]=[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/01/Create-Common-Directory-Group.png",alt:"Create Common Directory Group"},null,-1)])]),_:1})]),s[18]||(s[18]=a(`<p><em>創建公共目錄組</em></p><p>上面命令使用到的標誌和參數是：</p><ol><li><code>-a</code> – 將用户添加到增補組中。</li><li><code>-G</code> – 指定組名。</li><li><code>project</code> – 組名。</li><li><code>tecmint</code> – 已有的用户名。</li></ol><p>在這之後，給目錄配置適當的權限，<code>-R</code> 會讓操作遞歸進入子目錄中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chgrp -R project /var/www/reports/</span></span>
<span class="line"><span>$ sudo chmod -R 2775 /var/www/reports/</span></span></code></pre></div><p>解釋下上面 <code>chmod</code> 命令中的 <code>2775</code>：</p><ol><li><code>2</code> - 打開 setGID 位，意味着新創建的子文件繼承與目錄相同的組，新創建的子目錄繼承父目錄的 setGID 位。</li><li><code>7</code> - 為所有者提供 rwx 權限。</li><li><code>7</code> - 給組 rwx 權限。</li><li><code>5</code> - 為其他人提供 rx 權限。</li></ol><p>你可以使用下面的命令創建更多的系統用户並將它們添加到目錄組中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd -m -c &quot;Aaron Kili&quot; -s/bin/bash -G project aaronkilik</span></span>
<span class="line"><span>$ sudo useradd -m -c &quot;John Doo&quot; -s/bin/bash -G project john</span></span>
<span class="line"><span>$ sudo useradd -m -c &quot;Ravi Saive&quot; -s/bin/bash -G project ravi</span></span></code></pre></div><p>接着創建每個用户存儲他們項目報告的子目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /var/www/reports/aaronkilik_reports</span></span>
<span class="line"><span>$ sudo mkdir -p /var/www/reports/johndoo_reports</span></span>
<span class="line"><span>$ sudo mkdir -p /var/www/reports/ravi_reports</span></span></code></pre></div><p>現在你可以創建文件/文件，並分享給該組的其他用户了。</p>`,12)),t("p",null,[s[2]||(s[2]=i("就是這樣了！在本篇中，我們回顧瞭如何啓用所有用户對特定目錄的寫權限。要了解更多關於 Linux 中的用户/組，閲讀",-1)),n(e,{href:"http://www.tecmint.com/manage-users-and-groups-in-linux/"},{default:o(()=>[...s[1]||(s[1]=[i("如何管理用户/組和屬性",-1)])]),_:1}),s[3]||(s[3]=i("。",-1))]),s[19]||(s[19]=t("p",null,"記得在評論欄中留下你對這篇文章的想法。",-1)),s[20]||(s[20]=t("hr",null,null,-1)),s[21]||(s[21]=t("p",null,"譯者簡介：",-1)),s[22]||(s[22]=t("p",null,"Aaron Kili 是 Linux 和 F.O.S.S 愛好者，將來的 Linux SysAdmin 和 web 開發人員，目前是 TecMint 的內容創建者，他喜歡用電腦工作，並堅信分享知識。",-1)),s[23]||(s[23]=t("hr",null,null,-1)),t("p",null,[s[5]||(s[5]=i("via: ",-1)),n(e,{href:"http://www.tecmint.com/create-a-shared-directory-in-linux/"},{default:o(()=>[...s[4]||(s[4]=[i("http://www.tecmint.com/create-a-shared-directory-in-linux/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=i("作者：",-1)),n(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:o(()=>[...s[6]||(s[6]=[i("Aaron Kili",-1)])]),_:1}),s[10]||(s[10]=i(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...s[7]||(s[7]=[i("geekpi",-1)])]),_:1}),s[11]||(s[11]=i(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[12]||(s[12]=[i("LCTT",-1)])]),_:1}),s[15]||(s[15]=i(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...s[13]||(s[13]=[i("Linux中國",-1)])]),_:1}),s[16]||(s[16]=i(" 榮譽推出",-1))])])}const C=r(u,[["render",g]]);export{x as __pageData,C as default};
